/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_categories_after_update` AFTER UPDATE ON `tbc_categories` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.name <=> NEW.name) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('nombre: [',OLD.name,'] -> [',NEW.name,']')); END IF;
  IF NOT (OLD.description <=> NEW.description) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('descripción: [',COALESCE(OLD.description,'NULL'),'] -> [',COALESCE(NEW.description,'NULL'),']')); END IF;
  IF NOT (OLD.sup_id_category <=> NEW.sup_id_category) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('categoría superior: [',COALESCE(CAST(OLD.sup_id_category AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.sup_id_category AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.status <=> NEW.status) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('estado: [',IF(OLD.status=b'1','Activo','Inactivo'),'] -> [',IF(NEW.status=b'1','Activo','Inactivo'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tbc_categories','Update',USER(),CONCAT('Categoría actualizada. ID=',NEW.ID,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
