/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tbd_products_categories_after_update` AFTER UPDATE ON `tbd_products_categories` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.category_ID <=> NEW.category_ID) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('category_ID: [',OLD.category_ID,'] -> [',NEW.category_ID,']')); END IF;
  IF NOT (OLD.product_ID <=> NEW.product_ID) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('product_ID: [',OLD.product_ID,'] -> [',NEW.product_ID,']')); END IF;
  IF NOT (OLD.status <=> NEW.status) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('estado: [',IF(OLD.status=b'1','Activo','Inactivo'),'] -> [',IF(NEW.status=b'1','Activo','Inactivo'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tbd_products_categories','Update',USER(),CONCAT('Relación producto-categoría actualizada. category_ID=',NEW.category_ID,
      ', product_ID=',NEW.product_ID,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
